-- Solo para una base vacía. Si ya creaste las tablas, NO ejecutar.
BEGIN;
CREATE TABLE "ESPECIALISTA" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "correo_electronico" varchar(100) UNIQUE NOT NULL,
  "contrasena" varchar(42),
  "nombres" varchar(100),
  "ap_paterno" varchar(42),
  "ap_materno" varchar(42),
  "id_rol" int NOT NULL
);

CREATE TABLE "ROL" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(42),
  "descripcion" varchar(100)
);

CREATE TABLE "ROL_PERMISO" (
  "id_rol" int NOT NULL,
  "id_permiso" int NOT NULL,
  PRIMARY KEY ("id_rol", "id_permiso")
);

CREATE TABLE "PERMISO" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(42),
  "descripcion" varchar(100)
);

CREATE TABLE "ESPECIALISTA_ESPECIALIDAD" (
  "id_especialista" int NOT NULL,
  "id_especialidad" int NOT NULL,
  PRIMARY KEY ("id_especialista", "id_especialidad")
);

CREATE TABLE "ESPECIALIDAD" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(42),
  "descripcion" varchar(100)
);

CREATE TABLE "RESERVA" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "run" varchar(12) NOT NULL,
  "nombre" varchar(100) NOT NULL,
  "apellido" varchar(100) NOT NULL,
  "num_cel" varchar(9) NOT NULL,
  "correo_electronico" varchar(100) NOT NULL,
  "id_especialista" int NOT NULL,
  "id_especialidad" int NOT NULL,
  "fecha_inicio" timestamp NOT NULL,
  "fecha_fin" timestamp NOT NULL,
  "indicaciones_especiales" text,
  "estado" varchar(20) NOT NULL,
  "vencimiento_pago" timestamp,
  "google_event_id" varchar(255) UNIQUE
);

CREATE TABLE "DISPONIBILIDAD" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_especialista" int NOT NULL,
  "dia_semana" int NOT NULL,
  "hora_inicio" time NOT NULL,
  "hora_fin" time NOT NULL
);

CREATE TABLE "PAGO" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_reserva" int NOT NULL,
  "monto" int NOT NULL,
  "estado" varchar(20) NOT NULL,
  "orden_compra" varchar(100) UNIQUE NOT NULL,
  "token_webpay" varchar(255) UNIQUE,
  "fecha_pago" timestamp
);

ALTER TABLE "ESPECIALISTA" ADD FOREIGN KEY ("id_rol") REFERENCES "ROL" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ROL_PERMISO" ADD FOREIGN KEY ("id_rol") REFERENCES "ROL" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ROL_PERMISO" ADD FOREIGN KEY ("id_permiso") REFERENCES "PERMISO" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ESPECIALISTA_ESPECIALIDAD" ADD FOREIGN KEY ("id_especialista") REFERENCES "ESPECIALISTA" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ESPECIALISTA_ESPECIALIDAD" ADD FOREIGN KEY ("id_especialidad") REFERENCES "ESPECIALIDAD" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "DISPONIBILIDAD" ADD FOREIGN KEY ("id_especialista") REFERENCES "ESPECIALISTA" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "PAGO" ADD FOREIGN KEY ("id_reserva") REFERENCES "RESERVA" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "RESERVA" ADD FOREIGN KEY ("id_especialista", "id_especialidad") REFERENCES "ESPECIALISTA_ESPECIALIDAD" ("id_especialista", "id_especialidad") DEFERRABLE INITIALLY IMMEDIATE;

COMMIT;
